sys_ux_client_script.script:
/**
 * @param {params} params
 * @param {api} params.api
 * @param {TransformApiHelpers} params.helpers
 */
function evaluateProperty({
    api,
    helpers
}) {
    if (api.state.selectedRecord == null || api.state.selectedRecord == undefined)
        return {
            "minRatio": 0
        };
    return {};
}
